+    // and 4 are the two left reversed.
+    assert_eq!(first.flipped, vec![3]);
+    assert_eq!((first.contradictions, first.unresolved_edges, first.unresolved_pair), (2, 2, Some((1, 3))));
+}
+
+#[test]
