+fn votes(list: &[((u32, u32), Vote)]) -> BTreeMap<(u32, u32), Vote> {
+    list.iter().copied().collect()
+}
+
+#[test]
+fn many_shared_edges_outvote_one_whatever_the_face_numbers() {
