+
+#[test]
+fn a_shared_edge_outvotes_any_number_of_t_junction_votes() {
+    let (tris, ends) = mesh(&cube(0., 1.)[..3]);
+    let v = votes(&[
+        ((0, 1), Vote { exact: [1, 0], near: [0, 0] }),
+        ((0, 2), Vote { exact: [0, 0], near: [0, 9] }),
+        ((1, 2), Vote { exact: [1, 0], near: [0, 0] }),
